// === Tab: mySketch ===
let cols, rows;
let w = 19; // 波のグリッド間隔（大きくして計算負荷軽減）
let wave = [];
let particles = [];
let damping = 0.99; // 波の減衰

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);

  cols = floor(width / w);
  rows = floor(height / w);

  // 波の初期化
  for (let i = 0; i < cols; i++) {
    wave[i] = [];
    for (let j = 0; j < rows; j++) {
      wave[i][j] = 0;
    }
  }

  // ランダムなパーティクルの生成
  for (let i = 0; i < 100; i++) {
    particles.push(new Particle(random(-width/2, width/2), random(-height/2, height/2), random(-100, 100)));
  }
}

function draw() {
  background(10);
  orbitControl(); // 3D空間の操作

  updateWave(); // 波の更新
  drawWave();   // 波の描画

  for (let p of particles) {
    p.update(wave, cols, rows);
    p.show();
  }
}

// 波の更新（簡易版波動方程式）
function updateWave() {
  let newWave = [];
  for (let i = 0; i < cols; i++) {
    newWave[i] = [];
    for (let j = 0; j < rows; j++) {
      let sum = 0;
      let count = 0;
      if (i > 0) { sum += wave[i - 1][j]; count++; }
      if (i < cols - 1) { sum += wave[i + 1][j]; count++; }
      if (j > 0) { sum += wave[i][j - 1]; count++; }
      if (j < rows - 1) { sum += wave[i][j + 1]; count++; }

      newWave[i][j] = (sum / count) * damping; // 波の伝播と減衰
    }
  }
  wave = newWave;
}

// 波の描画
function drawWave() {
  stroke(255);
  noFill();

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      let h = wave[i][j] * 50;
      push();
      translate((i - cols / 2) * w, (j - rows / 2) * w, h);
      sphere(3);
      pop();
    }
  }
}

// パーティクルクラス
class Particle {
  constructor(x, y, z) {
    this.pos = createVector(x, y, z);
    this.vel = createVector();
    this.acc = createVector();
  }

  update(wave, cols, rows) {
    let i = floor((this.pos.x + width / 2) / w);
    let j = floor((this.pos.y + height / 2) / w);

    if (i >= 0 && i < cols && j >= 0 && j < rows) {
      let force = wave[i][j] * 0.2;
      this.acc.add(p5.Vector.random3D().mult(force));
    }

    this.vel.add(this.acc);
    this.vel.limit(2);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  show() {
    push();
    translate(this.pos.x, this.pos.y, this.pos.z);
    noStroke();
    fill(100, 150, 255);
    sphere(3);
    pop();
  }
}

// クリックで波を発生
function mousePressed() {
  var i = floor(random(0, cols));
  var j = floor(random(0, rows));
  wave[i][j] = 70; // 波の発生
}

